import React from 'react';

const SidebarLayout = ({ children, activeTab, setActiveTab }) => {
    const navItems = [
        { id: 'dashboard', label: '📊 Dashboard' },
        { id: 'discover', label: '🔍 Discover' },
        { id: 'matches', label: '💕 Matches' },
        { id: 'requests', label: '📬 Requests' },
        { id: 'sent-interests', label: '🚀 Sent Interests' },
        { id: 'chat', label: '💬 Chat' },
        { id: 'map', label: '📍 Nearby Map' },
        { id: 'passport', label: '🌍 Passport Mode' }
    ];

    return (
        <div style={{ display: 'flex', height: '100vh', backgroundColor: '#f3f4f6' }}>
            {/* Sidebar */}
            <div style={{ width: '250px', backgroundColor: '#ffffff', borderRight: '1px solid #e5e7eb', padding: '20px', display: 'flex', flexDirection: 'column' }}>
                <h2 style={{ fontSize: '1.5rem', fontWeight: 'bold', color: '#e11d48', marginBottom: '30px' }}>Penzi Admin</h2>
                <nav style={{ flex: 1 }}>
                    {navItems.map(item => (
                        <button
                            key={item.id}
                            onClick={() => setActiveTab(item.id)}
                            style={{
                                display: 'block',
                                width: '100%',
                                textAlign: 'left',
                                padding: '12px 16px',
                                marginBottom: '8px',
                                borderRadius: '8px',
                                border: 'none',
                                cursor: 'pointer',
                                backgroundColor: activeTab === item.id ? '#ffe4e6' : 'transparent',
                                color: activeTab === item.id ? '#e11d48' : '#4b5563',
                                fontWeight: activeTab === item.id ? 'bold' : 'normal',
                                transition: 'background-color 0.2s'
                            }}
                        >
                            {item.label}
                        </button>
                    ))}
                </nav>
                <button style={{ padding: '12px', border: 'none', backgroundColor: '#fef2f2', color: '#ef4444', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' }}>
                    Logout
                </button>
            </div>

            {/* Main Content Area */}
            <div style={{ flex: 1, overflowY: 'auto' }}>
                {children}
            </div>
        </div>
    );
};

export default SidebarLayout;
